create table fb_targeting_country_group
(
    id            bigint auto_increment comment 'id' primary key,
    unique_key    varchar(32) not null comment 'FB受众唯一Key',
    name          varchar(32) not null comment 'FB受众名称',
    type          varchar(32) not null comment 'FB受众类别(country:国家,city:城市,region区域)',
    country_codes text        not null comment 'FB国家受众编码数组',
    is_worldwide  tinyint(1) default 0 not null comment '是否是全球范围[0:false,1:true]',
    created       datetime default CURRENT_TIMESTAMP null,
    updated       datetime default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP
)ENGINE = INNODB COMMENT = 'FB受众国家组表';
-- 唯一索引
ALTER TABLE fb_targeting_country_group
    ADD UNIQUE INDEX uni_key_name(unique_key) USING BTREE;

